import { IngestPipeline } from "@514labs/moose-lib";

export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number | null;
}

// Optimized for queries:
// 1. Activity counts per user over a date range (user_id, event_ts)
// 2. Total duration per action type (action)
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["user_id", "event_ts", "action"]
  },
  stream: true,
  ingestApi: true,
});

